function App() {
  const answers = {
    'Above-the-fold hero': 'width/height + priority — it is the LCP, so preload it (no lazy-load)',
    'Thumbnail in a long grid': 'width/height + sizes, default lazy-load — small, off-screen images',
    'Full-bleed cover (unknown size)': 'fill + sizes + objectFit cover inside a relative container',
  };
  return (
    <ul style={{ fontFamily: 'system-ui', padding: 16 }}>
      {Object.entries(answers).map(([k, v]) => <li key={k}><b>{k}:</b> {v}</li>)}
    </ul>
  );
}

