// Fixed (illustrative) usage:
function App() {
  const fixed = [
    '// 1) Dimensions reserve space -> no shift; hero gets priority',
    '<Image src="/hero.jpg" width={1600} height={900} priority alt="Hero" />',
    '',
    '// 2) Thumbnails: dimensions, default lazy-load (no priority)',
    '<Image src="/thumb.jpg" width={80} height={80} alt="" />',
    '',
    '// 3) Allow the CDN host in next.config.js:',
    'images: { remotePatterns: [{ protocol: "https", hostname: "cdn.acme.com" }] }',
    '<Image src="https://cdn.acme.com/x.jpg" width={400} height={300} alt="" />',
  ];
  return (
    <pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>
      {fixed.join('\n')}
    </pre>
  );
}

